// From Nick Christensen's ads reporting starter (MIT), workshop "Ship ICP-driven ad campaigns and automated monitoring".
// Source: https://github.com/nickyc1/ship-icp-ads-automate-monitoring (n8n-ads-reporting/starter-workflow.json).
// Carried unchanged below this header.
// Grade every campaign on profit-to-spend, flag anomalies, and write a plain-language digest.
// Profit, not ROAS, is the hero number. Edit the targets to match your business.
const TARGET = { google: 1.5, meta: 0.5 };

const rows = $input.all().map(i => i.json);
const totalSpend = rows.reduce((s, r) => s + r.spend, 0);
const totalValue = rows.reduce((s, r) => s + r.conversion_value, 0);
const avgSpend = totalSpend / rows.length;

const graded = rows.map(r => {
  const ptos = r.conversion_value / r.spend;            // profit-to-spend proxy
  const target = TARGET[r.platform] ?? 1.0;
  const grade = ptos >= target ? "green" : "red";
  const anomaly = r.cpa > 2 * r.historical_cpa;
  let decision;
  if (grade === "red") decision = "Investigate or pause";
  else if (r.spend < avgSpend && r.conversions > 0) decision = "Scale (underfunded winner)";
  else decision = "Hold";
  return { ...r, ptos: Number(ptos.toFixed(2)), grade, decision, anomaly };
});

const attention = graded.filter(g => g.grade === "red" || g.anomaly);
const blended = (totalValue / totalSpend).toFixed(2);

const fmt = g => `${g.grade === "green" ? "🟢" : "🔴"} *${g.campaign}* (${g.platform}) — $${g.spend} spend, ${g.ptos}x value/spend → ${g.decision}${g.anomaly ? "  ⚠️ CPA 2x+ historical" : ""}`;

let digest = `📊 *Daily Paid Media Digest*\n`;
digest += `Spend $${totalSpend.toLocaleString()} · Value $${totalValue.toLocaleString()} · Blended ${blended}x\n\n`;
digest += `*Needs attention (${attention.length})*\n`;
digest += attention.length ? attention.map(fmt).join("\n") : "Nothing flagged. All campaigns at or above target.";
digest += `\n\n*All campaigns*\n`;
digest += graded.sort((a, b) => b.ptos - a.ptos).map(fmt).join("\n");
digest += `\n\n_You make the call. This is the analyst, not the boss._`;

return [{ json: { digest, campaign_count: graded.length, flagged: attention.length } }];

// Wraps the ads digest from Ads | Analyze (Nick Christensen's grading) into the report contract.
const p=$('Ads | Reporting period').first().json, s=$('Settings').first().json;
// A sample node that ran means sample rows reached the grading; once both are replaced (renamed), this is false.
const isSample=n=>{try{const j=$(n).first().json;return !!(j&&j.campaign!==undefined&&j.platform!==undefined);}catch(e){return false;}};
const sample=isSample('Ads | Google Ads (sample data)')||isSample('Ads | Meta Ads (sample data)');
const a=$('Ads | Analyze').first().json;
if(!a||typeof a.digest!=='string'||!a.campaign_count)throw Error('No ad data: Ads | Analyze returned no campaigns. Connect your ad platforms, or keep the two sample nodes switched on.');
if(/NaN|undefined/.test(a.digest))throw Error('Ad rows are missing fields: each row needs campaign, platform, spend, conversions, conversion_value, cpa and historical_cpa.');
const lines=[(sample?'SAMPLE DATA':'PRIVATE LIVE REVIEW')+' | '+s.storeName+' | Ads review (Google Ads and Meta)',p.start+' to '+p.end+' | '+s.currency,
  sample?'Sample data: the example campaigns from Nick Christensen\'s ads workshop, not your ad accounts. Replace the two sample nodes with your Google Ads and Meta data (same fields) to make this review live.':'Live data from your ad platforms.',
  '',a.digest,'',
  'Campaigns graded: '+a.campaign_count+'; flagged: '+a.flagged+'.',
  'Grades use value-to-spend against the targets at the top of Ads | Analyze. Platform-reported conversion value is not profit: set the targets from your margins.',
  'Review: check the flagged campaigns in the ad platform before changing any budget.'];
const markdown=lines.join('\n')+'\n';
return [{json:{markdown,slackText:markdown,fileName:'ads-'+p.start+'-to-'+p.end+'.md',period:p,sample}}];

const p=$('Ads | Reporting period').first().json,s=$('Settings').first().json;const j=$input.first().json,e=j.error??j;const reason=String(typeof e==='string'?e:(e.message||e.description||JSON.stringify(e))).replace(/[
]+/g,' ').slice(0,300);const markdown=['INCOMPLETE | '+s.storeName+' | Ads review (Google Ads and Meta)',p.start+' to '+p.end+' | '+s.currency,'','This review did not run, so it reports no figures this week. Missing figures are not zero.','Failed step: '+$prevNode.name,'Reason: '+reason,'','Review: fix the connection or setting named above, then run the workflow again.'].join('
